import java.awt.*;import java.awt.geom.*;import java.awt.image.*;import java.nio.file.*;import java.util.*;import javax.imageio.ImageIO;
/** Secondary motion and cartoon fall derived from existing illustrated pixels. */
public class BuildSpriteVariants {
 static Rectangle bounds(BufferedImage a){int l=a.getWidth(),t=a.getHeight(),r=-1,b=-1;for(int y=0;y<a.getHeight();y++)for(int x=0;x<a.getWidth();x++)if((a.getRGB(x,y)>>>24)>32){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y);}return new Rectangle(l,t,r-l+1,b-t+1);}
 static void variants(String pack,String from,String name,boolean fall)throws Exception{var source=ImageIO.read(Path.of("img",pack,from).toFile());var b=bounds(source);int s=source.getWidth();for(int i=0;i<4;i++){var out=new BufferedImage(s,s,2);var g=out.createGraphics();g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);if(fall){double angle=Math.toRadians(new int[]{0,25,55,90}[i]);double w=Math.abs(b.width*Math.cos(angle))+Math.abs(b.height*Math.sin(angle)),h=Math.abs(b.width*Math.sin(angle))+Math.abs(b.height*Math.cos(angle));g.translate(s/2.0,s-2-h/2);g.rotate(angle);g.translate(-b.getCenterX(),-b.getCenterY());}else{double sy=new double[]{1,.99,1.005,1}[i];g.translate(s/2.0,s-2);g.scale(1,sy);g.translate(-s/2.0,-s+2);}g.drawImage(source,0,0,null);g.dispose();Path p=Path.of("img",pack,"art",name,i+".png");Files.createDirectories(p.getParent());ImageIO.write(out,"png",p.toFile());}}
 static void titanWalk()throws Exception{
  var src=ImageIO.read(Path.of("img/ErenYeager/art/titan-idle/00.png").toFile());int s=256;
  Area left=new Area(new Polygon(new int[]{114,132,130,72,65,95},new int[]{174,179,254,255,245,203},6));Area right=new Area(new Polygon(new int[]{135,151,186,207,202,145},new int[]{178,172,216,255,255,253},6));Area upper=new Area(new Rectangle(0,0,s,s));upper.subtract(left);upper.subtract(right);
  for(int i=0;i<8;i++){double phase=i*Math.PI/4;BufferedImage big=new BufferedImage(768,768,2);Graphics2D g=big.createGraphics();g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);g.translate(s,s);
   for(int leg=0;leg<2;leg++){Graphics2D p=(Graphics2D)g.create();p.rotate(Math.toRadians(7*Math.sin(phase+(leg==0?0:Math.PI))),leg==0?122:144,177);p.setClip(leg==0?left:right);p.drawImage(src,0,0,null);p.dispose();}g.setClip(upper);g.drawImage(src,0,0,null);g.dispose();Rectangle b=bounds(big);BufferedImage out=new BufferedImage(s,s,2);g=out.createGraphics();g.drawImage(big,-s,s-2-(b.y+b.height-1),null);g.dispose();Path target=Path.of("img/ErenYeager/art/titan-walk",String.format("%02d.png",i));Files.createDirectories(target.getParent());ImageIO.write(out,"png",target.toFile());}
 }
 public static void main(String[]a)throws Exception{variants("Tom","art/Tom/00.png","idle",false);variants("Tom","art/Tom/15.png","ko",true);variants("Jerry","art/Jerry/00.png","idle",false);variants("Jerry","art/Jerry/14.png","ko",true);variants("ErenYeager","art/human-sheet/00.png","idle",false);variants("ErenYeager","art/ErenHumanMotion/16.png","ko",true);variants("ErenYeager","art/titan-idle/00.png","titan-ko",true);titanWalk();}
}
